"""The Boardwright MCP server.

It is the engine's tool surface under the Boardwright name, with
Boardwright's own instructions in front and Boardwright's tools added.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any

from . import __version__, engine, paths, prepare

SERVER_NAME = "boardwright"

PREAMBLE = """This is Boardwright, an AI design assistant for Altium Designer. The
boardwright skill holds the design procedure (schematic, library parts,
ERC, PCB layout, DRC, fab outputs); follow it when one applies. Call
boardwright_info once at the start of a design run: it gives the versions
and the folders for the verified-parts store, the fab profiles and the run
reports. When app_ping finds no bridge, boardwright_start_bridge starts it
in the running Altium; boardwright_doctor checks the whole set-up.

Two rules hold for every call:
- Save the target project or document by path. Never save the whole
  workspace (app_save_all): it writes other open projects and can raise
  a modal dialog that blocks the bridge.
- Board and library tools resolve "the active document". Focus the
  target (pcb_focus_board, or open the library by path) before editing.

"""


def _count_cards(folder: Path) -> int:
    cards = folder / "cards"
    return sum(1 for _ in cards.glob("*.md")) if cards.is_dir() else 0


def _build_info() -> dict[str, Any]:
    root = paths.install_root()
    if root is None:
        return {"install": "development"}
    stamp = root / "runtime" / "BUILD.json"
    try:
        return json.loads(stamp.read_text(encoding="utf-8-sig"))
    except (OSError, ValueError):
        return {"install": str(root), "build": "unknown"}


def _altium_registered() -> list[dict]:
    """Where Altium installs load the script project from (registry; [] if
    none is found, which some Altium versions show even when registered)."""
    try:
        from eda_agent import cli as engine_cli
        return engine_cli.registered_script_projects()
    except Exception:
        return []


def _run_command(*argv: str, timeout: int = 180) -> dict[str, Any]:
    """Run a Boardwright command in a child process and return its text.

    A child keeps the command's console output off this server's stdout,
    which carries the MCP protocol.
    """
    flags = ["-I"] if paths.install_root() is not None else []
    try:
        r = subprocess.run([sys.executable, *flags, "-m", "boardwright", *argv],
                           # Never hand the child this server's stdin: it is
                           # the MCP channel, and a child reading it hangs.
                           stdin=subprocess.DEVNULL,
                           capture_output=True, text=True, timeout=timeout,
                           encoding="utf-8", errors="replace",
                           creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                           env=dict(os.environ))
    except subprocess.TimeoutExpired:
        return {"ok": False, "exit_code": None,
                "output": f"timed out after {timeout} s"}
    text = "\n".join(part for part in (r.stdout.strip(), r.stderr.strip()) if part)
    return {"ok": r.returncode == 0, "exit_code": r.returncode, "output": text}


def info() -> dict[str, Any]:
    """Versions, folders and store contents, as one dict."""
    dirs = {name: {"path": str(p), "exists": p.is_dir()}
            for name, p in paths.data_dirs().items()}
    fab = sorted(p.stem for p in paths.fab_profiles().glob("*.json")) \
        if paths.fab_profiles().is_dir() else []
    root = paths.install_root()
    return {
        "boardwright": __version__,
        "install_root": str(root) if root else None,
        # The interpreter to run Boardwright commands with (setup, doctor,
        # relaunch): "<python>" -I -m boardwright <command>
        "python": str(Path(sys.executable).resolve()),
        "engine": {"package": engine.ENGINE_PACKAGE,
                   "version": engine.version(),
                   "based_on": engine.ENGINE_UPSTREAM},
        "build": _build_info(),
        "home": str(paths.home()),
        "folders": dirs,
        "script_project": str(paths.script_project()),
        "scripts_deployed": prepare.deployed_build(),
        "altium_registered": _altium_registered(),
        "verified_parts": _count_cards(paths.verified()),
        "fab_profiles": fab,
    }


def register_tools(mcp) -> None:
    @mcp.tool()
    def boardwright_info() -> dict:
        """Boardwright versions and the folders it uses.

        Returns the Boardwright and engine versions, the build stamp, the
        per-user folders (workspace, Altium scripts, verified parts, fab
        profiles, run reports) with whether each exists, how many verified
        parts the store holds and which fab profiles are saved. Call it
        once at the start of a design run instead of guessing paths.
        """
        return info()

    @mcp.tool()
    def boardwright_start_bridge(force: bool = False) -> dict:
        """Start the Boardwright bridge script inside the running Altium.

        Use it when app_ping reports no answer and Altium Designer is open.
        It hands StartMCPServer to Altium the way Altium's own Run Script
        menu does, and does nothing if the bridge already answers (unless
        force=True). It cannot start Altium itself. Ask the user first: it
        runs a script inside their Altium. If it fails, the user starts it
        by hand: File > Run Script > Altium_API > Dispatcher.pas >
        StartMCPServer. The script project must be registered once in
        Altium (Preferences > Scripting System > Global Projects > Install
        from file > the script_project path from boardwright_info).
        """
        args = ["relaunch"] + (["--force"] if force else [])
        return _run_command(*args)

    @mcp.tool()
    def boardwright_doctor(offline: bool = False) -> dict:
        """Check the Boardwright set-up on this PC and the live Altium link.

        Reports the runtime, the data folders, the deployed Altium scripts,
        other Altium servers that would fight over the bridge, and (unless
        offline=True) whether Altium and the bridge answer, each with the
        fix. Read-only.
        """
        return _run_command("doctor", *(["--offline"] if offline else []))


def build():
    """Import the engine, rename its server and add Boardwright's layer."""
    engine.configure()
    from eda_agent import server as engine_server

    mcp = engine_server.mcp
    if getattr(mcp, "_boardwright_built", False):
        return engine_server
    low = mcp._mcp_server
    low.name = SERVER_NAME
    low.version = __version__
    low.instructions = PREAMBLE + (low.instructions or "")
    register_tools(mcp)
    mcp._boardwright_built = True
    return engine_server


def serve() -> int:
    # The plugin has no setup step: get the PC ready before serving.
    prepare.ensure_ready()
    return int(build().serve_mcp(no_dashboard=True) or 0)
